    const value = values[i];

    if (!groupedData[region]) groupedData[region] = {};
    groupedData[region][metric] = value;
}

// Define the regions to exclude (optional)
const excludeRegions = ['Madrid', 'Canarias']; // Modify this list to exclude certain regions

// Filter regions to exclude
const filteredRegions = Object.keys(groupedData)
    .filter(region => {
