// Update series visibility based on legend interaction
chart.on('legendselectchanged', function (event) {
    const selectedRegions = event.selected; // Get the selected regions from the legend
    const visibleRegions = Object.keys(selectedRegions).filter(region => selectedRegions[region]); // Only selected regions

    // Update the series data to reflect visible regions
    const updatedSeries = selectedMetrics.map(metric => ({
