// Helper function to get diet data for a specific country and year
function getDietData(series_name, country_name) {
   const series = context.panel.data.series;

   // Log the available series for debugging
   console.log("Available Series Data:", series);

   // Find the series that has "country_str" field (this contains country names)
   const targetSeries = series.find((series_dict) => {
      const countryField = series_dict.fields.find(field => field.name === "country_str");
      return countryField && countryField.values.some(value => value === country_name);
   });

   if (!targetSeries) {
      console.log(`ERROR: Country "${country_name}" not found in series data.`);
      return [];
   }

   // Find the desired series based on the dynamic `series_name`
   const seriesField = targetSeries.fields.find((field) => field.name === series_name);
   if (!seriesField) {
      console.log(`ERROR: Series "${series_name}" not found in "${country_name}".`);
      return [];
   }

   // Find the "year_str" field
   const yearField = targetSeries.fields.find((field) => field.name === "year_str");
   const countryField = targetSeries.fields.find((field) => field.name === "country_str");
   const yearValues = yearField ? yearField.values.buffer || yearField.values : [];
   const countryValues = countryField ? countryField.values.buffer || countryField.values : [];
   const dietValues = seriesField.values.buffer || seriesField.values;

   // Create a map of year -> diet value for the current country
   let countryYearData = {};
   for (let i = 0; i < yearValues.length; i++) {
      if (countryValues[i] === country_name && yearValues[i] && dietValues[i]) {
         countryYearData[`${yearValues[i]}-${country_name}`] = dietValues[i]; // Map year-country pair to diet value
      }
   }

   console.log(`Mapped Data for "${country_name}":`, countryYearData);
   return countryYearData;
}

