// Helper function to extract region data
function getRegionData(region_name) {
   const series = context.panel.data.series;

   console.log("Available Series Data:", series);

   if (!series || series.length === 0) {
      console.log("ERROR: No series data available.");
      return {};
   }

   // Log field names to confirm actual names in your dataset
   console.log("Field names in dataset:", series[0].fields.map(f => f.name));

   // Identify correct field names for year, region, and value
   const dataSeries = series[0]; // Assuming all data is in the first series object
   const yearField = dataSeries.fields.find(field => field.name.includes("year"));
   const regionField = dataSeries.fields.find(field => field.name.includes("region"));
   const valueField = dataSeries.fields.find(field => !field.name.includes("year") && !field.name.includes("region"));

   if (!yearField || !regionField || !valueField) {
      console.log("ERROR: Could not detect correct field names for year, region, or value.");
      return {};
   }

   const years = yearField.values.buffer || yearField.values;
   const regions = regionField.values.buffer || regionField.values;
   const values = valueField.values.buffer || valueField.values;

   let regionYearData = {};
   for (let i = 0; i < years.length; i++) {
      if (regions[i] === region_name) {
         regionYearData[`${years[i]}-${region_name}`] = values[i];
      }
   }

   console.log(`Mapped Data for "${region_name}":`, regionYearData);
   return regionYearData;
}

// Helper function to get unique years
