   const dataSeries = series[0];
   const yearField = dataSeries.fields.find(field => field.name.includes("year"));
   if (!yearField) {
      console.log("ERROR: Year field not found.");
      return [];
   }

   const yearValues = yearField.values.buffer || yearField.values;
   return Array.from(new Set(yearValues)).sort(); // Ensure unique sorted years
}

