   const multiSelect_var = context.grafana.replaceVariables("${" + multiSelectVar_name + "}");
   result = multiSelect_var.replace(/{/, '').replace(/}/, '').split(',');
   return result;
}

function getSeriesByName(series_name) {
   return context
      .panel
      .data
      .series
      .map((series_dict) => {
         const series_temp = series_dict.fields.find((item) => item.name === series_name);
         if (!series_temp) {
            console.log(`ERROR (getSeriesByName): Could not find series: ${series_name}`);
            return null;
         }
         const seriesValues_temp = series_temp.values;
         return seriesValues_temp.buffer || seriesValues_temp;
      })[0];
}

function getVariable(variable_name) {
   return context.grafana.replaceVariables(`\${${variable_name}}`);
}

// === GET USER VARIABLES ===
const countries_strLst = getSelections("country_filter");
const series_lst = countries_strLst.map((country_name) => getSeriesByName(country_name));
const xaxis_ser = getSeriesByName("Year");

const age_str = getVariable('age_filter');
const sex_str = getVariable('sex_filter');
const crcFactor_str = getVariable('crcFactor_filter');

// === MAPPING FOR Y-AXIS LABEL BASED ON FACTOR VARIABLE ===
const crcLabelMap = {
   "CRC_incidence_val_Rate": "CRC Incidence Rate",
   "Colon and rectum cancer_Rate_DALYs_val": "CRC DALYs Rate",
   "Colon and rectum cancer_Rate_YLDs_val": "CRC YLDs Rate",
   "Colon and rectum cancer_Rate_YLLs_val": "CRC YLLs Rate"
};
const yAxisLabel = crcLabelMap[crcFactor_str] || "CRC Rate";

const seriesOptions_lst = series_lst.map((data_series, index) => ({
   data: data_series,
   type: 'line',
   name: countries_strLst[index]
}));

// === CHART OPTION ===
option = {
   title: {
      text: `${crcLabelMap[crcFactor_str]} - ${age_str === 'Age-standardized' ? 'Age Standardized Rate (ASR)' : `Age ${age_str}`} - ${sex_str === 'Both' ? 'Both Sexes' : sex_str}`,
   },
   legend: {
      type: 'plain',
      orient: 'vertical',
      left: 'right'
   },
   tooltip: {
      valueFormatter: (value) => parseFloat(value).toFixed(2)
   },
   xAxis: {
      name: 'Year',
      nameLocation: 'center',
      nameGap: 30,
      type: 'category',
      data: xaxis_ser
   },
   yAxis: {
      name: yAxisLabel,
      nameLocation: 'center',
      nameGap: 60,
      type: 'value',
      min: 0,
      axisLabel: {
         formatter: (value) => value.toFixed(0)
      }
   },
   dataZoom: [
      {
         type: 'slider',
         show: true,
         xAxisIndex: [0],
         start: 0,
         end: 100
      },
      {
         type: 'inside',
         xAxisIndex: [0],
         start: 0,
         end: 100
      }
   ],
   series: seriesOptions_lst
};

return option;

