options.getOption:
// Auxiliary function to get a query
function getQueryResult(query_name) {
   const result = context
      .panel
      .data
      .series
      .find((series_dict) =>
         series_dict['refId'] === query_name
      );
   if (!result) {
      console.log(`Error: Query with name ${query_name} not found`);
      return null;
   }
   return result['fields'];
}

// Auxiliary function to get a variable value
function getVariable(variable_name) {
   return context.grafana.replaceVariables(`\${${variable_name}}`);
}

// Get the policy filter variable value
const selectedPolicy_name = getVariable('policy_filter');

// Get Query A
const data_QueryResult = getQueryResult('A');
const dataTypeColumn_dict = data_QueryResult.find((element_dict) => element_dict['name'] === 'Type');
const policyTypes_strLst = dataTypeColumn_dict['values'];

const dataCountriesColumn_dict = data_QueryResult.find((element_dict) => element_dict['name'] === 'Country');
const dataCountries_strLst = dataCountriesColumn_dict['values'];

// Get Query B
const euCountries_QueryResult = getQueryResult('B');
const euCoutriesColumn_dict = euCountries_QueryResult.find((column_dict) => column_dict['name'] === 'Country');
const euCountries_strLst = euCoutriesColumn_dict['values'];

// Get Query C
const bestPractices_QueryResult = getQueryResult('C');
let bestPractices_dict = {};
if (bestPractices_QueryResult) {
   const bestPracticesCountriesColumn_dict = bestPractices_QueryResult.find((column_dict) => column_dict['name'] === 'Country');
   const bestPracticesCommentsColumn_dict = bestPractices_QueryResult.find((column_dict) => column_dict['name'] === 'Comment');

   if (bestPracticesCountriesColumn_dict && bestPracticesCommentsColumn_dict) {
      const bestPracticesCountriesColumn_strLst = bestPracticesCountriesColumn_dict['values'];
      const bestPracticesCommentsColumn_strLst = bestPracticesCommentsColumn_dict['values'];

      bestPracticesCountriesColumn_strLst.forEach((country_name, index_int) => {
         bestPractices_dict[country_name] = bestPracticesCommentsColumn_strLst[index_int];
      });
   } else {
      console.error('Error: Required columns ("Country" or "Comment") are missing in Best Practices Query.');
   }
} else {
   console.error('Error: Best Practices Query (C) did not return any results.');
}

// Initialize the countryPolicies_dict variable
let countryPolicies_dict = {};
euCountries_strLst.forEach((country_str) => {
   countryPolicies_dict[country_str] = [];
});

// Add the policies for each country
dataCountries_strLst.forEach((country_name, index_int) => {
   countryPolicies_dict[country_name].push(policyTypes_strLst[index_int]);
});

// onclick event to pass from the iframe to the window
context.panel.chart.on('click', function (params_dict) {
   const country_name = params_dict['name'];
   const clickData = {
      type: 'click-message',
      Country: country_name,
      "Best Practices": bestPractices_dict[country_name],
      Policies: countryPolicies_dict ? countryPolicies_dict[country_name] : [],
   };
   console.log(clickData);
   window.parent.postMessage(clickData, "*"); // Sends data to parent iframe
});

// Function to format the tooltip
function tooltipFormatter_fun(params_dict, ticket, callback) {
   const country_name = params_dict['name'];
   const policies_cnt = params_dict['value'];

   if (!(country_name in countryPolicies_dict)) {
      return `<p>Policies: non EU MS</p>`;
   }

   const policies_strLst = countryPolicies_dict[country_name];

   if (policies_strLst.length === 0) {
      return `<p>Policies: None</p>`;
   }

   // Adjust the count by ignoring "Best Practices"
   const adjustedPoliciesCnt = policies_strLst.includes("Best Practices")
      ? policies_cnt - 1
      : policies_cnt;

   const tooltip_html = policies_strLst
      .map((policyType_str) => `<li>${policyType_str}</li>`)
      .join('');

   return `
      <p>Policies: ${adjustedPoliciesCnt}</p>
         `;
}

// This section is for the legend
let maxPolicies_f = 0;
let data_opt = [];
for (const key in countryPolicies_dict) {
   const policies_strLst = countryPolicies_dict[key];

   // Exclude "Best Practices" from the count
   const adjustedCount = policies_strLst.includes("Best Practices ")
      ? policies_strLst.length - 1
      : policies_strLst.length;

   data_opt.push({
      name: key,
      value: adjustedCount,
   });

   maxPolicies_f = Math.max(maxPolicies_f, adjustedCount);
}

// The echarts option
option = {
   title: {
      text: 'Number of CRC Prevention Policies per Country',
      left: 'center',
      top: 0,
   },
   tooltip: {
      trigger: 'item',
      formatter: tooltipFormatter_fun,
   },
   visualMap: {
      min: 0,
      max: maxPolicies_f,
      left: 'left',
      top: 'bottom',
      text: ['High', 'Low'],
      calculable: true,
   },
   graphic: [
      {
         type: 'text',
         left: '10',
         bottom: 200, // Position relative to the visualMap
         style: {
            text: 'High and low values refer to the number of policies per domain per country.',
            font: '14px Arial',
            fill: '#000', // Text color
            lineHeight: 18,
            width: 200, // Restrict the width of the text
            overflow: 'break', // Truncate text if it overflows
         },
      },
   ],
   series: [
      {
         name: selectedPolicy_name,
         type: 'map',
         mapType: 'world', // Use 'world' map type, or you can use specific region map type if available
         center: [15, 50], // Center the map on Europe
         zoom: 6,
         roam: false,
         label: {
            show: false,
         },
         data: data_opt,
      },
   ],
};

return option;

