options.getOption:
const mapName = "Spanish Regions";

// Function to get query results from Grafana data source
function getQueryResult(query_name) {
   const result = context?.panel?.data?.series?.find(series => series.refId === query_name);
   if (!result || !result.fields) {
      console.error(`Error: Query with name ${query_name} not found or has no fields`);
      return null;
   }
   return result.fields;
}

// Get GeoJSON Data from Business Input Data Source
const geoJsonQuery = getQueryResult('B');
if (!geoJsonQuery) {
   console.error('Error: GeoJSON query did not return results.');
   return {};
}

// Extract GeoJSON field
const geoJsonField = geoJsonQuery.find(field => field.name === 'json');
if (!geoJsonField || !geoJsonField.values || geoJsonField.values.length === 0) {
   console.error('Error: GeoJSON field is missing or empty.');
   return {};
}

// Parse the GeoJSON string into an object safely
let geoJsonData;
try {
   geoJsonData = JSON.parse(geoJsonField.values[0]);
} catch (error) {
   console.error('Error parsing GeoJSON:', error);
   return {};
}

// Debugging log
console.log('Loaded GeoJSON:', geoJsonData);

// Register the GeoJSON map in ECharts
context.echarts.registerMap(mapName, geoJsonData);

// Get region names from Query A
const regionQuery = getQueryResult('A');  // Query returning "region_str"
if (!regionQuery) {
   console.error('Error: Region query did not return results.');
   return {};
}

// Extract Region Names
const regionField = regionQuery.find(field => field.name === 'region_str');
if (!regionField || !regionField.values) {
   console.error('Error: Region field is missing.');
   return {};
}

// Map regions to required format with a value of 296
const regionsData = regionField.values.map(region => ({ name: region, value: 296 }));

// Debugging log
console.log('Regions Data:', regionsData);

// Create a Set for quick lookup of highlighted regions
const highlightedRegions = new Set(regionsData.map(region => region.name));

// Define ECharts option
const option = {
   title: { text: 'Spanish Regions Map', left: 'left' },
   tooltip: {
      trigger: 'item',
      formatter: function (params) {
         // Show tooltip only for highlighted regions
         return highlightedRegions.has(params.name) ? `${params.name}: ${params.value}%` : '';
      }
   },
   visualMap: {
      min: 0,
      max: 300,
      left: 'left',
      top: 'bottom',
      text: ['High', 'Low'],
      calculable: false,
      inRange: {
         color: ['#A8E6A2', '#005500']  // Light green to dark green
      }
   },
   series: [
      {
         name: 'Regions',
         type: 'map',
         map: mapName,  // Ensure the map name matches the registered one
         roam: true,
         label: {
            show: true,
            formatter: function (params) {
               return highlightedRegions.has(params.name) ? params.name : '';  // Show name only if in `regionsData`
            }
         },
         emphasis: {
            label: { show: true }
         },
         data: geoJsonData.features.map(feature => ({
            name: feature.properties.name,
            value: highlightedRegions.has(feature.properties.name) ? 296 : 0  // Dark green for selected, light for others
         }))
      }
   ]
};

// Return the chart option
return option;

